:root { --font-sans: "Inter Variable", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif; --font-mono: "JetBrains Mono Variable", ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace; --radius-s: 6px; --radius-m: 10px; --radius-l: 16px; --ease-out: cubic-bezier(.22, 1, .36, 1); --topbar-h: 56px; --bottombar-h: 68px; color-scheme: light; --bg: #f6f5f1; --bg-grid: #14171c0b; --surface: #fff; --surface-2: #f1f0eb; --surface-3: #e9e7e0; --line: #e3e1da; --line-strong: #cfccc2; --text: #15181d; --text-2: #4a515c; --text-3: #6b7280; --accent: #d9480f; --accent-text: #b93c0a; --accent-soft: #fde8dc; --accent-contrast: #fff; --cmd: #2563eb; --cmd-soft: #e0e9fd; --evt: #0f8a5f; --evt-soft: #dcf3e9; --cmp: #7c3aed; --cmp-soft: #ede5fd; --ext: #6b7280; --danger: #d92d3f; --danger-soft: #fde2e5; --warn: #b45309; --warn-soft: #fdf0d9; --shadow-1: 0 1px 2px #10141a0f, 0 2px 8px #10141a0a; --shadow-2: 0 2px 6px #10141a0f, 0 16px 40px #10141a1f; --scrim: #0e11166b; }
