*, ::before, ::after { box-sizing: border-box; }
html, body { height: 100%; }
body { background: var(--bg); color: var(--text); font-family: var(--font-sans); -webkit-font-smoothing: antialiased; font-feature-settings: "cv11", "ss01"; margin: 0px; font-size: 16px; line-height: 1.6; transition: background-color 0.25s, color 0.25s; }
button { font: inherit; color: inherit; }
a { color: var(--accent-text); }
[data-tape-focus-visible] { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 4px; }
::selection { background: var(--accent-soft); color: var(--text); }
.mono { font-family: var(--font-mono); }
.sr-only { clip: rect(0px, 0px, 0px, 0px); white-space: nowrap; border: 0px; width: 1px; height: 1px; margin: -1px; padding: 0px; position: absolute; overflow: hidden; }
.btn { border: 1px solid var(--line-strong); background: var(--surface); height: 40px; color: var(--text); cursor: pointer; transition: background .15s ease, border-color .15s ease, transform .15s var(--ease-out), opacity .15s; white-space: nowrap; border-radius: 999px; align-items: center; gap: 0.5rem; padding: 0px 16px; font-size: 0.925rem; font-weight: 550; text-decoration: none; display: inline-flex; }
.btn[data-tape-hover] { background: var(--surface-2); }
.btn[data-tape-active] { transform: scale(0.98); }
.btn[disabled] { opacity: 0.4; cursor: default; }
.btn--primary { background: var(--accent); border-color: var(--accent); color: var(--accent-contrast); }
.btn--primary[data-tape-hover] { background: var(--accent); filter: brightness(1.08); }
.btn--ghost { background: 0px 0px; border-color: rgba(0, 0, 0, 0); }
.btn--ghost[data-tape-hover] { background: var(--surface-2); }
.btn--sm { height: 32px; padding: 0px 12px; font-size: 0.84rem; }
.icon-btn { cursor: pointer; width: 36px; height: 36px; color: var(--text-2); background: 0px 0px; border: 1px solid rgba(0, 0, 0, 0); border-radius: 999px; place-items: center; display: inline-grid; }
.icon-btn[data-tape-hover] { background: var(--surface-2); color: var(--text); }
kbd { font-family: var(--font-mono); color: var(--text-3); border-top-color: ; border-top-style: ; border-top-width: ; border-right-color: ; border-right-style: ; border-right-width: ; border-bottom-color: ; border-bottom-style: ; border-left-color: ; border-left-style: ; border-left-width: ; border-image-source: ; border-image-slice: ; border-image-width: ; border-image-outset: ; border-image-repeat: ; border-bottom-width: 2px; border-radius: 4px; padding: 0px 5px; font-size: 0.72rem; }
.prose p { margin: 0px 0px 0.9em; }
.prose p:last-child { margin-bottom: 0px; }
.prose strong { color: var(--text); font-weight: 650; }
.prose em { font-style: italic; }
.prose ul, .prose ol { margin: 0px 0px 0.9em; padding-left: 1.2em; }
.prose li { margin: 0.3em 0px; }
.prose li::marker { color: var(--text-3); }
.prose code, .prose .msg { font-family: var(--font-mono); font-size: 0.86em; }
.concept-chip { color: inherit; cursor: pointer; text-decoration-line: underline; text-decoration-style: dotted; text-decoration-color: var(--accent); text-underline-offset: 4px; font-weight: 600; text-decoration-thickness: 1.5px; }
.concept-chip[data-tape-hover], .concept-chip[data-tape-focus-visible] { color: var(--accent-text); }
.doc-ref { vertical-align: 1px; border: 1px solid var(--line-strong); background: var(--surface-2); font-family: var(--font-mono); letter-spacing: 0.02em; color: var(--text-2); cursor: pointer; border-radius: 999px; align-items: center; gap: 4px; margin: 0px 2px; padding: 1px 7px; font-size: 0.7rem; font-weight: 600; line-height: 1.6; display: inline-flex; }
.doc-ref[data-tape-hover], .doc-ref[data-tape-focus-visible] { border-color: var(--accent); color: var(--accent-text); }
.tok { font-family: var(--font-mono); white-space: nowrap; border-radius: 5px; padding: 1px 6px; font-size: 0.82em; font-weight: 600; }
.tok--cmd { color: var(--cmd); background: var(--cmd-soft); }
.tok--evt { color: var(--evt); background: var(--evt-soft); }
.tok--cmp { color: var(--cmp); background: var(--cmp-soft); }
.doc-html h1, .doc-html h2, .doc-html h3 { margin: 1.4em 0px 0.5em; font-size: 1.05rem; line-height: 1.3; }
.doc-html h1:first-child, .doc-html h2:first-child { margin-top: 0px; }
.doc-html table { border-collapse: collapse; width: 100%; margin: 1em 0px; font-size: 0.88rem; display: block; overflow-x: auto; }
.doc-html th, .doc-html td { border: 1px solid var(--line); text-align: left; vertical-align: top; padding: 6px 8px; }
.doc-html th { background: var(--surface-2); }
.doc-html img { border: 1px solid var(--line); background: rgb(255, 255, 255); border-radius: 6px; max-width: 100%; height: auto; }
.doc-html pre { background: var(--surface-2); border-radius: 8px; padding: 10px; font-size: 0.82rem; overflow-x: auto; }
.doc-html code { font-family: var(--font-mono); font-size: 0.86em; }
.doc-html .modal-figure { margin: 1rem 0px; }
.doc-html figcaption { color: var(--text-3); margin-top: 0.4rem; font-size: 0.82rem; }
@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after { transition-duration: 0.001ms !important; animation-duration: 0.001ms !important; }
}
.lang { border: 1px solid var(--line); border-radius: 999px; flex: 0 0 auto; padding: 2px; display: inline-flex; }
.lang__opt { min-width: 30px; height: 26px; font-family: var(--font-mono); letter-spacing: 0.04em; color: var(--text-3); border-radius: 999px; place-items: center; padding: 0px 8px; font-size: 0.72rem; font-weight: 600; text-decoration: none; display: inline-grid; }
a.lang__opt[data-tape-hover] { color: var(--text); background: var(--surface-2); }
.lang__opt[aria-current] { background: var(--surface-3); color: var(--text); }
.app { grid-template-rows: var(--topbar-h) minmax(0, 1fr) var(--bottombar-h); height: 100dvh; display: grid; overflow: hidden; }
.topbar { border-bottom: 1px solid var(--line); background: color-mix(in srgb, var(--bg) 88%, transparent); backdrop-filter: blur(8px); z-index: 5; align-items: center; gap: 14px; padding: 0px 16px 0px 18px; display: flex; position: relative; }
.brand { color: var(--text); letter-spacing: -0.01em; align-items: center; gap: 8px; font-weight: 700; text-decoration: none; display: inline-flex; }
.brand__mark { background: var(--accent); width: 28px; height: 28px; color: var(--accent-contrast); border-radius: 8px; place-items: center; display: grid; }
.brand__mark svg { width: 16px; height: 16px; }
.chapter-btn { border: 1px solid var(--line); background: var(--surface); cursor: pointer; min-width: 0px; height: 36px; color: var(--text); border-radius: 999px; align-items: center; gap: 10px; padding: 0px 10px 0px 12px; display: inline-flex; }
.chapter-btn[data-tape-hover] { border-color: var(--line-strong); }
.chapter-btn__n { color: var(--accent-text); font-size: 0.74rem; font-weight: 600; }
.chapter-btn__t { white-space: nowrap; text-overflow: ellipsis; font-size: 0.9rem; font-weight: 600; overflow: hidden; }
.chapter-btn svg { color: var(--text-3); flex: 0 0 auto; }
.rail { flex: 1 1 0%; align-items: center; gap: 3px; min-width: 60px; max-width: 520px; margin-left: auto; display: flex; }
.rail__seg { background: var(--line); border-radius: 2px; flex: 1 1 0%; height: 4px; transition: background 0.3s; }
.rail__seg.is-done { background: color-mix(in srgb, var(--accent) 45%, var(--line)); }
.rail__seg.is-current { background: var(--accent); }
.main { grid-template-rows: minmax(0px, 1fr); grid-template-columns: minmax(340px, clamp(360px, 34vw, 500px)) minmax(0px, 1fr); gap: 0px; min-height: 0px; display: grid; }
.panel { overscroll-behavior: contain; border-right: 1px solid var(--line); scrollbar-width: thin; scrollbar-color: var(--line-strong) transparent; min-height: 0px; overflow-y: auto; }
.panel__inner { padding: clamp(24px, 4.5vh, 48px) clamp(20px, 2.6vw, 40px) 32px; }
.panel__kicker { letter-spacing: 0.08em; text-transform: uppercase; color: var(--accent-text); margin: 0px 0px 10px; font-size: 0.74rem; font-weight: 600; }
.panel__title { letter-spacing: -0.025em; text-wrap: balance; margin: 0px 0px 18px; font-size: clamp(1.45rem, 1.1rem + 1vw, 2rem); font-weight: 700; line-height: 1.15; }
.panel__body { color: var(--text-2); font-size: clamp(0.98rem, 0.9rem + 0.2vw, 1.06rem); line-height: 1.65; }
.prose.panel__body > * + * { margin-top: 14px; }
.panel__body > p { margin-bottom: 0px; }
.stage { background: radial-gradient(circle at 1px 1px, var(--bg-grid) 1px, transparent 0) 0 0 / 22px 22px, var(--bg); grid-template-rows: auto minmax(0px, 1fr); min-width: 0px; min-height: 0px; display: grid; position: relative; }
.stage__tools { flex-wrap: wrap; justify-content: flex-end; gap: 6px; min-height: 42px; padding: 12px 14px 0px; display: flex; }
.stage__tool { border: 1px solid var(--line); background: var(--surface); height: 30px; color: var(--text-2); cursor: pointer; border-radius: 999px; align-items: center; gap: 6px; padding: 0px 12px; font-size: 0.8rem; font-weight: 550; display: inline-flex; }
.stage__tool[data-tape-hover] { color: var(--text); border-color: var(--line-strong); }
.stage__tool[aria-pressed="true"] { color: var(--accent-text); border-color: var(--accent); }
.stage__canvas { grid-row: 2; grid-template-rows: minmax(0px, 1fr); grid-template-columns: minmax(0px, 1fr); min-height: 0px; padding: clamp(12px, 2.4vh, 28px) clamp(12px, 2.2vw, 36px); display: grid; position: relative; }
.scene, .fit, .fit__in { grid-template-rows: minmax(0px, 1fr); grid-template-columns: minmax(0px, 1fr); min-width: 0px; min-height: 0px; display: grid; }
.zoom-root { z-index: 60; place-items: center; padding: clamp(12px, 3vh, 32px) clamp(12px, 3vw, 40px); display: grid; position: fixed; inset: 0px; }
.zoom-scrim { background: var(--scrim); backdrop-filter: blur(2px); position: absolute; inset: 0px; }
.zoom { background: var(--bg); border: 1px solid var(--line); border-radius: var(--radius-l); width: 100%; max-width: 1600px; height: 100%; box-shadow: var(--shadow-2); grid-template-rows: auto minmax(0px, 1fr); display: grid; position: relative; overflow: hidden; }
.zoom__head { border-bottom: 1px solid var(--line); background: var(--surface); justify-content: space-between; align-items: center; gap: 12px; padding: 10px 12px 10px 20px; display: flex; }
.zoom__title { letter-spacing: -0.01em; white-space: nowrap; text-overflow: ellipsis; font-size: 0.98rem; font-weight: 650; overflow: hidden; }
.zoom__ctl { flex: 0 0 auto; align-items: center; gap: 2px; display: inline-flex; }
.zoom__ctl .icon-btn[disabled] { opacity: 0.35; cursor: default; }
.zoom__level { border: 1px solid var(--line); background: var(--surface-2); min-width: 56px; height: 32px; color: var(--text-2); cursor: pointer; border-radius: 8px; padding: 0px 8px; font-size: 0.8rem; font-weight: 600; }
.zoom__level[data-tape-hover] { color: var(--text); border-color: var(--line-strong); }
.zoom__sep { background: var(--line); width: 1px; height: 22px; margin: 0px 6px; }
.zoom__body { background: radial-gradient(circle at 1px 1px, var(--bg-grid) 1px, transparent 0) 0 0 / 22px 22px, var(--bg); min-height: 0px; position: relative; overflow: hidden; }
.zoom__body.is-zoomed { cursor: grab; scrollbar-width: thin; scrollbar-color: var(--line-strong) transparent; overflow: auto; }
.zoom__body.is-zoomed[data-tape-active] { cursor: grabbing; }
.zoom__canvas { box-sizing: border-box; width: calc(var(--z,1) * 100%); height: calc(var(--z,1) * 100%); grid-template-rows: minmax(0px, 1fr); grid-template-columns: minmax(0px, 1fr); padding: clamp(16px, 3vh, 36px) clamp(16px, 3vw, 48px); display: grid; }
@media (width <= 900px) {
  .zoom-root { padding: 0px; }
  .zoom { border: 0px; border-radius: 0px; }
  .zoom__canvas { padding: 10px; }
  .zoom__body .dg-wrap { overflow: auto; }
}
.evidence { grid-template-rows: minmax(0px, 1fr) auto; gap: 10px; min-height: 0px; margin: 0px; display: grid; }
.evidence__plate { border-radius: var(--radius-m); border: 1px solid var(--line); cursor: zoom-in; background: rgb(255, 255, 255); grid-template-rows: minmax(0px, 1fr); grid-template-columns: minmax(0px, 1fr); place-items: center; min-height: 0px; padding: 12px; display: grid; overflow: hidden; }
.evidence__plate img { object-fit: contain; width: 100%; height: 100%; min-height: 0px; display: block; }
.evidence figcaption { color: var(--text-3); text-align: center; font-size: 0.84rem; }
.as-text { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius-l); max-width: 62ch; max-height: 100%; color: var(--text-2); place-self: center; padding: 24px 28px; overflow-y: auto; }
.bottombar { border-top: 1px solid var(--line); background: var(--bg); justify-content: space-between; align-items: center; gap: 12px; padding: 0px 16px; display: flex; }
.counter { cursor: pointer; min-width: 0px; color: var(--text-2); background: 0px 0px; border: 0px; border-radius: 8px; align-items: center; gap: 12px; padding: 6px 10px; display: inline-flex; }
.counter[data-tape-hover] { background: var(--surface-2); }
.counter .mono { color: var(--text); font-size: 0.88rem; font-weight: 600; }
.counter__of { color: var(--text-3); font-weight: 500; }
.counter__t { white-space: nowrap; text-overflow: ellipsis; max-width: 32ch; font-size: 0.88rem; overflow: hidden; }
.counter__keys { gap: 3px; display: inline-flex; }
.mini-cards { gap: 8px; display: grid; }
.mini-card { border: 1px solid var(--line); background: var(--surface); border-radius: var(--radius-m); padding: 12px 14px; }
.mini-card__top { justify-content: space-between; align-items: baseline; gap: 8px; margin-bottom: 4px; display: flex; }
.mini-card__top strong { color: var(--text); font-size: 0.96rem; }
.mini-card__tag { font-family: var(--font-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--text-3); white-space: nowrap; font-size: 0.66rem; }
.mini-card__body { font-size: 0.92rem; line-height: 1.55; }
.callout { border-radius: var(--radius-m); border: 1px solid var(--line); background: var(--surface); padding: 12px 14px; font-size: 0.95rem; }
.callout__title { color: var(--text); align-items: center; gap: 7px; margin-bottom: 4px; font-size: 0.9rem; font-weight: 650; display: flex; }
.callout--info { border-color: color-mix(in srgb, var(--cmd) 40%, var(--line)); background: color-mix(in srgb, var(--cmd-soft) 55%, var(--surface)); }
