.c11-inv__total .mono { font-size: 1.15rem; }
.c11-inv__scen { color: var(--text-3); justify-content: flex-end; gap: 18px; padding: 0px 10px; font-size: 0.74rem; display: flex; }
.c11-inv__scen strong { color: var(--text-2); font-weight: 650; }
.c11-inv__hidden { border: 1.5px dashed var(--line-strong); border-radius: var(--radius-m); gap: 4px; padding: 10px 12px; transition: border-color 0.3s, background-color 0.3s; display: grid; }
.c11-inv__hidden.is-on { border-color: var(--accent); background: color-mix(in srgb, var(--accent-soft) 45%, transparent); }
.c11-inv__hk { letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-3); font-size: 0.68rem; font-weight: 700; }
.c11-inv__hidden.is-on .c11-inv__hk { color: var(--accent-text); }
.c11-inv__hq { color: var(--text-3); font-size: 0.85rem; font-style: italic; }
.c11-inv__hrow { color: var(--text-2); gap: 1px; font-size: 0.88rem; line-height: 1.35; display: grid; }
.c11-inv__hrow strong { color: var(--accent-text); font-size: 0.98rem; }
.c11-card { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius-l); width: 100%; max-width: 700px; box-shadow: var(--shadow-1); place-self: center; gap: 6px; padding: 24px 28px 22px; display: grid; }
.c11-card__k { letter-spacing: 0.1em; text-transform: uppercase; color: var(--accent-text); margin: 0px; font-size: 0.7rem; font-weight: 700; }
.c11-card__t { letter-spacing: -0.02em; margin: 0px 0px 8px; font-size: 1.5rem; font-weight: 750; line-height: 1.2; }
.c11-card__list { gap: 8px; margin: 0px; padding: 0px; list-style: none; display: grid; }
.c11-card__list li { border: 1px solid var(--line); border-radius: var(--radius-m); background: var(--surface-2); grid-template-columns: 22px 36px minmax(0px, 1fr) auto; align-items: center; gap: 12px; padding: 10px 12px; display: grid; }
.c11-card__n { color: var(--accent-text); text-align: center; font-size: 0.95rem; font-weight: 700; }
.c11-card__ic { background: var(--accent); width: 36px; height: 36px; color: var(--accent-contrast); border-radius: 10px; place-items: center; display: grid; }
.c11-card__body { gap: 1px; min-width: 0px; line-height: 1.3; display: grid; }
.c11-card__body strong { font-size: 0.98rem; }
.c11-card__q { color: var(--text-2); font-size: 0.88rem; }
.c11-card__ch { color: var(--cmp); background: var(--cmp-soft); white-space: nowrap; border-radius: 6px; align-self: start; margin-top: 2px; padding: 2px 7px; font-size: 0.68rem; font-weight: 600; }
.c11-card__foot { flex-wrap: wrap; justify-content: center; gap: 10px; margin-top: 12px; display: flex; }
.c11-card__foot .btn { text-decoration: none; }
